package net.civeira.phylax.features.access.userinvitation.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.features.access.userinvitation.domain.UserInvitation;
import net.civeira.phylax.features.access.userinvitation.domain.valueobject.RolesVO;

@RequiredArgsConstructor
public class RolesValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<RolesVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getRoles() {
    return value.flatMap(RolesVO::getRoles);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<RolesVO> getRolesValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public RolesVO readRoles(final Optional<UserInvitation> original,
      final ConstraintFailList fails) {
    return value.orElse(original.map(UserInvitation::getRolesValue).orElseGet(RolesVO::nullValue));
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param roles
   * @return
   */
  public T roles(RolesVO roles) {
    this.value = Optional.of(roles);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param roles
   * @return
   */
  public T roles(Optional<RolesVO> roles) {
    this.value = roles;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param roles
   * @return
   */
  public T roles(String roles) {
    this.value = Optional.of(RolesVO.from(roles));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T rolesNull() {
    this.value = Optional.empty();
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetRoles() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetRolesIfMatches(final String field) {
    if ("roles".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
